    pub render: crate::SongLuaOverlayState,
}
struct Actor {
    scene: u64,
    state: ActorSnapshot,
    current: TweenPose,
    queue: VecDeque<TweenStep>,
    hibernate: f32,
    update_rate: f32,
    started: bool,
    update_error_reported: bool,
    load_name: Option<Vec<u8>>,
    parent: Option<TableId>,
