) -> mlua::Result<mlua::Lua> {
    crate::compile::migration_actor_control_with_context(source, context)
}

pub fn begin_legacy_actor_playback(lua: &mlua::Lua) -> mlua::Result<()> {
    let actors = crate::lua_util::song_lua_actor_registry(lua)?
        .sequence_values::<mlua::Table>()
        .collect::<mlua::Result<Vec<_>>>()?;
    crate::lua_util::begin_live_actor_playback(lua, &actors)
}

/// The production host wraps the upstream empty declaration in a live actor.
pub fn legacy_null_actor(lua: &mlua::Lua) -> mlua::Result<mlua::Table> {
    crate::compile::migration_null_actor_control(lua)
}

pub fn legacy_actor_message_identities(lua: &mlua::Lua) -> mlua::Result<Vec<usize>> {
    crate::lua_util::song_lua_actor_registry(lua)?
        .sequence_values::<mlua::Table>()
        .map(|actor| actor.map(|actor| actor.to_pointer() as usize))
        .collect()
}

pub fn broadcast_legacy_actor_message(
    lua: &mlua::Lua,
    name: &str,
    params: Option<mlua::Value>,
    native: bool,
) -> mlua::Result<()> {
    if native {
        crate::lua_util::broadcast_native_song_lua_message(lua, name, params)
    } else {
        crate::lua_util::broadcast_song_lua_message(lua, name, params)
    }
}

pub fn start_legacy_actor_scene(lua: &mlua::Lua) -> mlua::Result<()> {
    let root: mlua::Table = lua.globals().get("root")?;
    if root
        .raw_get::<Option<bool>>("__songlua_startup_commands_ran")?
        .unwrap_or(false)
    {
        return Ok(());
    }
    crate::lua_util::run_actor_named_command(lua, &root, "BeginCommand")?;
    crate::lua_util::run_named_command_on_children_recursively(lua, &root, "BeginCommand", None)?;
    crate::lua_util::run_actor_startup_commands_for_table(lua, &root)
}

pub fn advance_legacy_actor_scene(lua: &mlua::Lua, seconds: f64, delta: f64) -> mlua::Result<()> {
    let root: mlua::Value = lua.globals().get("root")?;
    crate::lua_util::set_live_frame(lua, seconds, seconds * 2.0, delta);
    crate::lua_util::run_actor_compile_update_functions_with_delta(lua, &root, delta)
}

/// The actual End command walker. LiveScene's subsequent owner Stop events are
/// checked separately; this control does not duplicate that output policy.
pub fn end_legacy_actor_tree(lua: &mlua::Lua) -> mlua::Result<()> {
    let root = lua.globals().get("root")?;
    crate::lua_util::end_actor_scene(lua, &root)
}

/// Local render values from the actual production reader and tween queue.
/// Traversal is preorder, before ancestor composition or effect evaluation.
pub fn legacy_actor_render_states(
    lua: &mlua::Lua,
) -> Result<Vec<crate::SongLuaOverlayState>, String> {
    legacy_render_states(lua, None, false)
}

pub fn legacy_actor_effect_states(
    lua: &mlua::Lua,
    frame_clock: [f32; 2],
) -> Result<Vec<crate::SongLuaOverlayState>, String> {
    legacy_render_states(lua, Some(frame_clock), false)
}

/// Local poses in tree order, visiting wrappers after ordinary children.
pub fn legacy_wrapped_actor_effect_states(
    lua: &mlua::Lua,
    frame_clock: [f32; 2],
) -> Result<Vec<crate::SongLuaOverlayState>, String> {
    legacy_render_states(lua, Some(frame_clock), true)
}

fn legacy_render_states(
    lua: &mlua::Lua,
    frame_clock: Option<[f32; 2]>,
    include_wrappers: bool,
) -> Result<Vec<crate::SongLuaOverlayState>, String> {
    fn visit(
        lua: &mlua::Lua,
        actor: &mlua::Table,
        out: &mut Vec<crate::SongLuaOverlayState>,
        frame_clock: Option<[f32; 2]>,
        include_wrappers: bool,
    ) -> Result<(), String> {
        let mut state = crate::lua_util::live_actor_overlay_state(lua, actor)?;
        crate::lua_util::replay_tween_pose(lua, actor, &mut state);
        if let Some(frame_clock) = frame_clock {
            state.effect_time = crate::lua_util::effect_render_time(actor, frame_clock)
                .map_err(|error| error.to_string())?;
            state.spin_baked = crate::lua_util::spin_render_pose(actor)
                .map_err(|error| error.to_string())?
                .is_some();
        }
        out.push(state);
        for child in
            crate::lua_util::actor_direct_children(lua, actor).map_err(|error| error.to_string())?
        {
            visit(lua, &child, out, frame_clock, include_wrappers)?;
        }
        if include_wrappers {
            for wrapper in crate::lua_util::actor_wrappers(lua, actor)
                .map_err(|error| error.to_string())?
                .sequence_values::<mlua::Table>()
            {
                visit(
                    lua,
                    &wrapper.map_err(|error| error.to_string())?,
                    out,
                    frame_clock,
                    true,
                )?;
            }
        }
        Ok(())
    }
    let root = lua
        .globals()
        .get("root")
        .map_err(|error| error.to_string())?;
    let mut out = Vec::new();
    visit(lua, &root, &mut out, frame_clock, include_wrappers)?;
    Ok(out)
}

